BEGIN;
TRUNCATE TABLE public.cis_policies;
INSERT INTO public.cis_policies (id_cis, titulo, descripcion, comando_remediacion, check_comprobacion, estado, fecha_ultimo_analisis) VALUES
(26000, 'Exigir historial de contraseñas', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'net accounts /UNIQUEPW:24', 'c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "PasswordHistorySize"; Remove-Item $env:TEMP\secpol.cfg -> n:PasswordHistorySize = (\d+) compare >= 24', 'pendiente', NULL),
(26002, 'Edad mínima de la contraseña', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'net accounts /MINPWAGE:1', 'c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "MinimumPasswordAge"; Remove-Item $env:TEMP\secpol.cfg -> n:MinimumPasswordAge = (\d+) compare >= 1', 'pendiente', NULL),
(26003, 'Longitud mínima de la contraseña', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'net accounts /MINPWLEN:14', 'c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "MinimumPasswordLength"; Remove-Item $env:TEMP\secpol.cfg -> n:MinimumPasswordLength = (\d+) compare >= 14', 'pendiente', NULL),
(26004, 'Relajar los límites de longitud mínima de contraseña', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'reg add "HKLM\System\CurrentControlSet\Control\SAM" /v RelaxMinimumPasswordLengthLimits /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\SAM
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\SAM -> RelaxMinimumPasswordLengthLimits
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\SAM -> RelaxMinimumPasswordLengthLimits -> 1', 'pendiente', NULL),
(26005, 'Duración del bloqueo de cuenta', 'Endurece el bloqueo de cuentas para frenar intentos repetidos de autenticación fallida.', 'net accounts /lockoutduration:15', 'c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "LockoutDuration"; Remove-Item $env:TEMP\secpol.cfg -> n:LockoutDuration = (\d+) compare >= 15', 'pendiente', NULL),
(26006, 'Umbral de bloqueo de cuenta', 'Endurece el bloqueo de cuentas para frenar intentos repetidos de autenticación fallida.', 'net accounts /lockoutthreshold:5', 'c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "LockoutBadCount"; Remove-Item $env:TEMP\secpol.cfg -> n:LockoutBadCount = (\d+) compare <= 5
c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "LockoutBadCount"; Remove-Item $env:TEMP\secpol.cfg -> n:LockoutBadCount = (\d+) compare > 0', 'pendiente', NULL),
(26007, 'Restablecer el contador de bloqueo de cuenta después de', 'Endurece el bloqueo de cuentas para frenar intentos repetidos de autenticación fallida.', 'net accounts /lockoutwindow:5', 'c:powershell secedit /export /cfg $env:TEMP\secpol.cfg; Get-Content $env:TEMP\secpol.cfg | Select-String "ResetLockoutCount"; Remove-Item $env:TEMP\secpol.cfg -> n:ResetLockoutCount = (\d+) compare >= 15', 'pendiente', NULL),
(26008, 'Cuentas: Bloquear cuentas Microsoft', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'reg add "HKLM\Software\Microsoft\Windows\CurrentVersion\Policies\System" /v NoConnectedUser /t REG_DWORD /d 3 /f', 'r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> NoConnectedUser
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> NoConnectedUser -> 3', 'pendiente', NULL),
(26009, 'Cuentas: Estado de la cuenta Invitado', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'net user invitado /active:no', 'c:powershell -NoProfile -Command "[bool](Get-CimInstance -Query ''SELECT * FROM Win32_UserAccount WHERE LocalAccount = TRUE AND SID LIKE ''''S-1-5-21-%-501'''''' | Where-Object -Property Disabled)" -> r:True', 'pendiente', NULL),
(26010, 'Cuentas: Limitar el uso de cuentas locales con contraseñas en blanco solo al inicio de sesión en consola', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'reg delete "HKLM\System\CurrentControlSet\Control\Lsa" /v LimitBlankPasswordUse /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa -> LimitBlankPasswordUse
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa -> LimitBlankPasswordUse -> 1', 'pendiente', NULL),
(26011, 'Cuentas: Cambiar el nombre de la cuenta de administrador', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'Rename-LocalUser -Name "Administrador" -NewName "adm_local_srv"', 'not c:net user -> r:Admin|Администратор|Amministratore|Beheerder|Järjestelmänvalvoja|Správce|Rendszergazda|Yönetici |Διαχειριστής|管理者|管理员|系統管理員|관리자|مسؤول | מנהל |ผู้ดูแลระบบ', 'pendiente', NULL),
(26012, 'Cuentas: Cambiar el nombre de la cuenta de invitado', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'Rename-LocalUser -Name "invitado" -NewName "usuario_invitado"', 'not c:net user -> r:guest|Guest|Gast|Invité|Invitado|Ospite|Convidado|Gäst |Gjest|Gæst|Vieras|Гость|Gość|Vendég|Host |Misafir|Επισκέπτης|ゲスト|来宾|來賓|게스트|ضيف|אורח|บัญชีผู้ใช้ทั่วไป', 'pendiente', NULL),
(26013, 'Auditoría: Forzar que las subcategorías de auditoría reemplacen a las categorías', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'reg add "HKLM\System\CurrentControlSet\Control\Lsa" /v SCENoApplyLegacyAuditPolicy /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa -> SCENoApplyLegacyAuditPolicy
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa -> SCENoApplyLegacyAuditPolicy -> 1', 'pendiente', NULL),
(26014, 'Auditoría: Apagar el sistema inmediatamente si no se pueden registrar auditorías de seguridad', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'reg delete "HKLM\System\CurrentControlSet\Control\Lsa" /v CrashOnAuditFail /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa -> CrashOnAuditFail
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Lsa -> CrashOnAuditFail -> 0', 'pendiente', NULL),
(26015, 'Devices: Impedir que los usuarios instalen controladores de impresora', 'Restringe hardware, controladores o periféricos para reducir riesgos físicos y vectores de entrada no deseados.', 'reg add "HKLM\System\CurrentControlSet\Control\Print\Providers\LanMan Print Services\Servers" /v AddPrinterDrivers /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Print\Providers\LanMan Print Services\Servers
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Print\Providers\LanMan Print Services\Servers -> AddPrinterDrivers
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Print\Providers\LanMan Print Services\Servers -> AddPrinterDrivers -> 1', 'pendiente', NULL),
(26016, 'Miembro del dominio: Cifrar o firmar digitalmente los datos del canal seguro (siempre)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg add "HKLM\System\CurrentControlSet\Services\Netlogon\Parameters" /v RequireSignOrSeal /t REG_DWORD /d 1 /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> RequireSignOrSeal
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> RequireSignOrSeal -> 1', 'pendiente', NULL),
(26017, 'Miembro del dominio: Cifrar digitalmente los datos del canal seguro (cuando sea posible)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\Netlogon\Parameters" /v SealSecureChannel /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> SealSecureChannel
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> SealSecureChannel -> 1', 'pendiente', NULL),
(26018, 'Miembro del dominio: Firmar digitalmente los datos del canal seguro (cuando sea posible)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\Netlogon\Parameters" /v SignSecureChannel /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> SignSecureChannel
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> SignSecureChannel -> 1', 'pendiente', NULL),
(26019, 'Miembro del dominio: Deshabilitar los cambios de contraseña de la cuenta de equipo', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'reg delete "HKLM\System\CurrentControlSet\Services\Netlogon\Parameters" /v DisablePasswordChange /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> DisablePasswordChange
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> DisablePasswordChange -> 0', 'pendiente', NULL),
(26021, 'Miembro del dominio: Requerir clave de sesión segura (Windows 2000 o posterior)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\Netlogon\Parameters" /v RequireStrongKey /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> RequireStrongKey
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\Netlogon\Parameters -> RequireStrongKey -> 1', 'pendiente', NULL),
(26022, 'Inicio de sesión interactivo: No requerir CTRL+ALT+DEL', 'Protege el proceso de inicio de sesión reduciendo exposición de cuentas, sesiones y credenciales.', 'reg add "HKLM\Software\Microsoft\Windows\CurrentVersion\Policies\System" /v DisableCAD /t REG_DWORD /d 0 /f', 'r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> DisableCAD
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> DisableCAD -> 0', 'pendiente', NULL),
(26023, 'Inicio de sesión interactivo: No mostrar el último usuario conectado', 'Protege el proceso de inicio de sesión reduciendo exposición de cuentas, sesiones y credenciales.', 'reg add "HKLM\Software\Microsoft\Windows\CurrentVersion\Policies\System" /v DontDisplayLastUserName /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> DontDisplayLastUserName
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> DontDisplayLastUserName -> 1', 'pendiente', NULL),
(26024, 'Inicio de sesión interactivo: Umbral de bloqueo de la cuenta del equipo', 'Endurece el bloqueo de cuentas para frenar intentos repetidos de autenticación fallida.', 'reg add "HKLM\Software\Microsoft\Windows\CurrentVersion\Policies\System" /v MaxDevicePasswordFailedAttempts /t REG_DWORD /d 30 /f', 'not r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> MaxDevicePasswordFailedAttempts -> 0
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> MaxDevicePasswordFailedAttempts
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> MaxDevicePasswordFailedAttempts -> n:^(\d+) compare <=30', 'pendiente', NULL),
(26025, 'Inicio de sesión interactivo: Límite de inactividad del equipo', 'Protege el proceso de inicio de sesión reduciendo exposición de cuentas, sesiones y credenciales.', 'reg add "HKLM\Software\Microsoft\Windows\CurrentVersion\Policies\System" /v InactivityTimeoutSecs /t REG_DWORD /d 900 /f', 'not r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> InactivityTimeoutSecs -> 0
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> InactivityTimeoutSecs
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\Policies\System -> InactivityTimeoutSecs -> n:^(\d+) compare <= 900', 'pendiente', NULL),
(26026, '"Inicio de sesión interactivo: Texto del mensaje para los usuarios que intentan iniciar sesión"', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'reg add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\system" /v legalnoticetext /t REG_SZ /d "El acceso a este sistema está restringido a usuarios autorizados. El uso no autorizado puede tener consecuencias legales." /f', 'not c:reg query HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\system /v legalnoticetext -> r:\s+legalnoticetext\s+REG_SZ\s+$', 'pendiente', NULL),
(26027, '"Inicio de sesión interactivo: Título del mensaje para los usuarios que intentan iniciar sesión"', 'Aplica la directiva indicada para endurecer la configuración de seguridad del sistema según el benchmark CIS.', 'reg add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\system" /v legalnoticecaption /t REG_SZ /d "AVISO LEGAL" /f', 'not c:reg query HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\system /v legalnoticecaption -> r:\s+legalnoticecaption\s+REG_SZ\s+$', 'pendiente', NULL),
(26028, 'Inicio de sesión interactivo: Número de inicios de sesión anteriores que se almacenan en caché', 'Protege el proceso de inicio de sesión reduciendo exposición de cuentas, sesiones y credenciales.', 'reg add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon" /v CachedLogonsCount /t REG_DWORD /d 4 /f', 'r:HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon
r:HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon -> CachedLogonsCount
r:HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon -> CachedLogonsCount -> n:^(\d+) compare <= 4', 'pendiente', NULL),
(26030, '''Inicio de sesión interactivo: Comportamiento al retirar la tarjeta inteligente'' is set a ''Lock Workstation'' or higher', 'Protege el proceso de inicio de sesión reduciendo exposición de cuentas, sesiones y credenciales.', 'reg add "HKLM\Software\Microsoft\Windows NT\CurrentVersion\Winlogon" /v ScRemoveOption /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows NT\CurrentVersion\Winlogon
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows NT\CurrentVersion\Winlogon -> ScRemoveOption
r:HKEY_LOCAL_MACHINE\Software\Microsoft\Windows NT\CurrentVersion\Winlogon -> ScRemoveOption -> r:^1$|^2$|^3$', 'pendiente', NULL),
(26031, 'Cliente de red de Microsoft: Firmar digitalmente las comunicaciones (siempre)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg add "HKLM\System\CurrentControlSet\Services\LanmanWorkstation\Parameters" /v RequireSecuritySignature /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters -> RequireSecuritySignature
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters -> RequireSecuritySignature -> 1', 'pendiente', NULL),
(26032, 'Cliente de red de Microsoft: Firmar digitalmente las comunicaciones (si el servidor lo permite)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\LanmanWorkstation\Parameters" /v EnableSecuritySignature /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters -> EnableSecuritySignature
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters -> EnableSecuritySignature -> 1', 'pendiente', NULL),
(26033, 'Cliente de red de Microsoft: Enviar contraseña sin cifrar a servidores SMB de terceros', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'reg delete "HKLM\System\CurrentControlSet\Services\LanmanWorkstation\Parameters" /v EnablePlainTextPassword /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters -> EnablePlainTextPassword
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanmanWorkstation\Parameters -> EnablePlainTextPassword -> 0', 'pendiente', NULL),
(26034, 'Servidor de red de Microsoft: Amount de idle time required before suspending session', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\LanManServer\Parameters" /v AutoDisconnect /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> AutoDisconnect
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> AutoDisconnect -> n:^(\d+) compare <= 15', 'pendiente', NULL),
(26035, 'Servidor de red de Microsoft: Firmar digitalmente las comunicaciones (siempre)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg add "HKLM\System\CurrentControlSet\Services\LanManServer\Parameters" /v RequireSecuritySignature /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> RequireSecuritySignature
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> RequireSecuritySignature -> 1', 'pendiente', NULL),
(26036, 'Servidor de red de Microsoft: Digitally sign communications (if client agrees)', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg add "HKLM\System\CurrentControlSet\Services\LanManServer\Parameters" /v EnableSecuritySignature /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> EnableSecuritySignature
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> EnableSecuritySignature -> 1', 'pendiente', NULL),
(26037, 'Servidor de red de Microsoft: Disconnect clients cuando logon hours expire', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\LanManServer\Parameters" /v EnableForcedLogOff /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> EnableForcedLogOff
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> EnableForcedLogOff -> 1', 'pendiente', NULL),
(26038, '''Servidor de red de Microsoft: Servidor SPN target name validation level'' is set a ''Accept if provided by client'' or higher', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg add "HKLM\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters" /v SMBServerNameHardeningLevel /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters -> SMBServerNameHardeningLevel
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters -> SMBServerNameHardeningLevel -> n:^(\d+) compare >= 1', 'pendiente', NULL),
(26039, 'Acceso de red: Do not permitir anonymous enumeration de SAM accounts', 'Endurece la comunicación de red y el acceso remoto aplicando restricciones, firmas o valores más seguros.', 'reg delete "HKLM\SYSTEM\CurrentControlSet\Control\Lsa" /v RestrictAnonymousSAM /f', 'not r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa
not r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa -> RestrictAnonymousSAM
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa -> RestrictAnonymousSAM -> 1', 'pendiente', NULL),
(26040, 'Acceso de red: Do not permitir anonymous enumeration de SAM accounts y shares', 'Endurece la comunicación de red y el acceso remoto aplicando restricciones, firmas o valores más seguros.', 'reg add "HKLM\SYSTEM\CurrentControlSet\Control\Lsa" /v RestrictAnonymous /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa -> RestrictAnonymous
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa -> RestrictAnonymous -> 1', 'pendiente', NULL),
(26041, 'No permitir almacenar contraseñas y credenciales para autenticación de red', 'Refuerza la política de contraseñas para endurecer el uso, la rotación o la recuperación de credenciales.', 'reg add "HKLM\SYSTEM\CurrentControlSet\Control\Lsa" /v DisableDomainCreds /t REG_DWORD /d 1 /f', 'r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa -> DisableDomainCreds
r:HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Lsa -> DisableDomainCreds -> 1', 'pendiente', NULL),
(26043, 'Acceso de red: Named Pipes that can be accessed anonymously', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', 'reg delete "HKLM\System\CurrentControlSet\Services\LanManServer\Parameters" /v NullSessionPipes /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> NullSessionPipes
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\LanManServer\Parameters -> NullSessionPipes -> r:\S+', 'pendiente', NULL),
(26044, '''Acceso de red: Remotely accessible registry paths'' is configured', 'Endurece la comunicación de red y el acceso remoto aplicando restricciones, firmas o valores más seguros.', 'reg delete "HKLM\System\CurrentControlSet\Control\SecurePipeServers\Winreg\AllowedExactPaths" /v Machine /f', 'not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\SecurePipeServers\Winreg\AllowedExactPaths
not r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\SecurePipeServers\Winreg\AllowedExactPaths -> Machine
r:HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\SecurePipeServers\Winreg\AllowedExactPaths -> Machine -> r:System\\CurrentControlSet\\Control\\ProductOptions System\\CurrentControlSet\\Control\\Server Applications Software\\Microsoft\\Windows NT\\CurrentVersion', 'pendiente', NULL),
(26045, '''Acceso de red: Remotely accessible registry paths y sub-paths'' is configured', 'Configura el servicio indicado para reducir superficie de ataque o impedir funciones innecesarias en el equipo.', '$paths = @(
  "Software\Microsoft\OLAP Server",
  "Software\Microsoft\Windows NT\CurrentVersion\Perflib",
  "Software\Microsoft\Windows NT\CurrentVersion\Print",
  "Software\Microsoft\Windows NT\CurrentVersion\Windows",
  "System\CurrentControlSet\Control\ContentIndex",
  "System\CurrentControlSet\Control\Print\Printers",
  "System\CurrentControlSet\Control\Terminal Server",
  "System\CurrentControlSet\Control\Terminal Server\DefaultUserConfiguration",
  "System\CurrentControlSet\Control\Terminal Server\UserConfig",
  "System\CurrentControlSet\Services\Eventlog",
  "System\CurrentControlSet\Services\SysmonLog"
